mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=4 unions=(0,1),(1,2) checkpoint union=(2,3) rollback query=(0,3)","false"),
        ("n=3 unions=(0,1) checkpoint union=(1,2) rollback query=(0,1)","true"),
        ("n=4 unions=(0,1) checkpoint union=(1,2) rollback query=(0,2)","false"),
        ("n=2 unions= checkpoint union=(0,1) rollback query=(0,1)","false"),
        ("n=3 unions=(0,1),(1,2) checkpoint union=(0,2) rollback query=(0,2)","true"),
        ("  \nn=4 unions=(0,1),(1,2) checkpoint union=(2,3) rollback query=(0,3)\n  ","false"),
        ("\nn=3 unions=(0,1),(1,2) checkpoint union=(0,2) rollback query=(0,2)\n","true")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS dsu-rollback");
}
